//! Internal slot representations and containers for formwork structures.
//!
//! # Warning
//! This module contains **internal plumbing** types used by code generated by `#[formwork]`.
//! Application code and end users should not interact with [`Slot`], [`SingleSlot`], or [`MultiSlot`] directly.
//! Use macro-generated builders, [`SingleChoice`],
//! [`MultiChoice`], and the [`Formwork`] trait instead.

use crate::choice::{Freeform, MultiChoice, SingleChoice};
use crate::error::FormworkError;
#[cfg(doc)]
use crate::formwork_trait::Formwork;
use serde::{Deserialize, Serialize};

/// Internal plumbing: generic container representing a slot in a formwork structure.
///
/// Holds either a choice `C`, a fixed wet value `W`, or a fixed dry value `D`.
#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Slot<W, D, C> {
    /// Slot contains a choice `C` waiting to be resolved.
    Choose(C),
    /// Slot contains a fixed, wet value `W`.
    FixedWet(W),
    /// Slot contains a fixed, dry value `D`.
    FixedDry(D),
}

/// Internal plumbing: slot specialization for [`SingleChoice`].
pub type SingleSlot<W, D> = Slot<W, D, SingleChoice<W>>;

/// Internal plumbing: slot specialization for [`MultiChoice`].
///
/// Holds either a [`MultiChoice<W>`] choice or a fixed collection (`Vec<W>` / `Vec<D>`).
pub type MultiSlot<W, D> = Slot<Vec<W>, Vec<D>, MultiChoice<W>>;

/// Internal plumbing: slot specialization for [`Freeform`].
pub type FreeformSlot<W, D> = Slot<W, D, Freeform<W>>;

impl<W, D, C> Slot<W, D, C> {
    /// Returns a reference to the inner choice if this slot is a [`Slot::Choose`].
    pub fn as_choice(&self) -> Option<&C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }

    /// Returns a mutable reference to the inner choice if this slot is a [`Slot::Choose`].
    pub fn as_choice_mut(&mut self) -> Option<&mut C> {
        match self {
            Slot::Choose(c) => Some(c),
            _ => None,
        }
    }

    /// Returns a reference to the inner wet value if this slot is a [`Slot::FixedWet`].
    pub fn as_wet(&self) -> Option<&W> {
        match self {
            Slot::FixedWet(w) => Some(w),
            _ => None,
        }
    }

    /// Returns a reference to the inner dry value if this slot is a [`Slot::FixedDry`].
    pub fn as_dry(&self) -> Option<&D> {
        match self {
            Slot::FixedDry(d) => Some(d),
            _ => None,
        }
    }
}

impl<W, D> From<SingleChoice<W>> for SingleSlot<W, D> {
    fn from(choice: SingleChoice<W>) -> Self {
        Slot::Choose(choice)
    }
}

impl<W, D> From<MultiChoice<W>> for MultiSlot<W, D> {
    fn from(choice: MultiChoice<W>) -> Self {
        Slot::Choose(choice)
    }
}

impl<W, D> From<W> for SingleSlot<W, D> {
    fn from(value: W) -> Self {
        Slot::FixedWet(value)
    }
}

impl<W, D> From<Vec<W>> for MultiSlot<W, D> {
    fn from(value: Vec<W>) -> Self {
        Slot::FixedWet(value)
    }
}

impl<W, D> From<Freeform<W>> for FreeformSlot<W, D> {
    fn from(choice: Freeform<W>) -> Self {
        Slot::Choose(choice)
    }
}

impl<W, D> From<W> for FreeformSlot<W, D> {
    fn from(value: W) -> Self {
        Slot::FixedWet(value)
    }
}

impl<W, D> SingleSlot<W, D> {
    /// Returns `true` if this slot contains an unconfirmed choice.
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot contains a confirmed choice.
    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot is complete (fixed value or confirmed choice).
    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedWet(_) | Slot::FixedDry(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }
}

impl<T> SingleSlot<T, T> {
    /// Resolves the single slot into its concrete value.
    ///
    /// For non-cascading slots where $W = D$, pre-resolved values stored in
    /// [`Slot::FixedDry`] are returned directly as `Ok(val)`.
    ///
    /// # Errors
    /// Returns [`FormworkError::WetChoice`] if the slot contains an unconfirmed choice.
    pub fn resolve_exact(self) -> Result<T, FormworkError> {
        match self {
            Slot::FixedWet(w) => Ok(w),
            Slot::FixedDry(d) => Ok(d),
            Slot::Choose(c) => c.resolve_exact(),
        }
    }
}

impl<W, D> MultiSlot<W, D> {
    /// Returns `true` if this slot contains an unconfirmed choice.
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot contains a confirmed choice.
    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot is complete (fixed collection or confirmed choice).
    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedWet(_) | Slot::FixedDry(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }
}

impl<T> MultiSlot<T, T> {
    /// Resolves the multi-slot into a collection of concrete values without synthetic wrapping.
    ///
    /// For non-cascading pick slots ($W = D$), pre-resolved values stored in
    /// [`Slot::FixedDry`] are returned directly as `Ok(val)`.
    ///
    /// # Errors
    /// Returns [`FormworkError::WetChoice`] if the slot contains an unconfirmed choice.
    pub fn resolve(self) -> Result<Vec<T>, FormworkError> {
        match self {
            Slot::FixedWet(w) => Ok(w),
            Slot::FixedDry(d) => Ok(d),
            Slot::Choose(c) => c.resolve(),
        }
    }
}

impl<W, D> FreeformSlot<W, D> {
    /// Returns `true` if this slot contains an unconfirmed choice.
    pub fn is_pending(&self) -> bool {
        match self {
            Slot::Choose(c) => !c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot contains a confirmed choice.
    pub fn is_made(&self) -> bool {
        match self {
            Slot::Choose(c) => c.is_made(),
            _ => false,
        }
    }

    /// Returns `true` if this slot is complete (fixed value or confirmed choice).
    pub fn is_complete(&self) -> bool {
        match self {
            Slot::FixedWet(_) | Slot::FixedDry(_) => true,
            Slot::Choose(c) => c.is_made(),
        }
    }
}

impl<T> FreeformSlot<T, T> {
    /// Resolves the freeform slot into its concrete value.
    ///
    /// For non-cascading slots where $W = D$, pre-resolved values stored in
    /// [`Slot::FixedDry`] are returned directly as `Ok(val)`.
    ///
    /// # Errors
    /// Returns [`FormworkError::WetChoice`] if the slot contains an unconfirmed choice.
    pub fn resolve_exact(self) -> Result<T, FormworkError> {
        match self {
            Slot::FixedWet(w) => Ok(w),
            Slot::FixedDry(d) => Ok(d),
            Slot::Choose(c) => c.resolve_exact(),
        }
    }

    /// Alias for [`resolve_exact`](Self::resolve_exact).
    pub fn resolve(self) -> Result<T, FormworkError> {
        self.resolve_exact()
    }
}
